<script setup>
/**
 * Detail Kehadiran — susunannya DIRENDER DARI METADATA doctype, bukan ditulis
 * ulang di sini. Section, kolom, urutan, label, dan aturan depends_on dibaca
 * saat runtime dari `frappe.desk.form.load.getdoctype`, jadi tampilannya sama
 * dengan form desk dan ikut berubah sendiri kalau doctype-nya diubah.
 *
 * Pola yang sama dipakai MasterKaryawanDetail.vue; di sini versinya lebih
 * ringkas karena Kehadiran tidak punya tab, child table, maupun lampiran.
 *
 * Seperti desk, field kosong TETAP ditampilkan (bernilai "—") supaya jumlah dan
 * susunan field benar-benar sama, bukan hanya yang kebetulan terisi.
 */
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'

const DOCTYPE = 'Kehadiran'
const route = useRoute()
const router = useRouter()
const name = computed(() => route.params.name)

// Kembali ke bulan yang sedang dilihat, bukan selalu ke bulan berjalan.
const kembali = computed(() => ({
	name: 'Kehadiran',
	query: route.query.bulan ? { bulan: route.query.bulan, tahun: route.query.tahun } : {},
}))

const errorMessage = ref('')

const docRes = createResource({
	url: 'juragan.api.portal.kehadiran.get_kehadiran',
	method: 'GET',
	auto: true,
	makeParams: () => ({ name: name.value }),
	onSuccess: () => {
		errorMessage.value = ''
	},
	onError: (e) => {
		errorMessage.value = e?.messages?.[0] || e?.message || 'Gagal memuat data kehadiran.'
	},
})
const d = computed(() => docRes.data || null)

const metaFields = ref([])
const metaSiap = ref(false)
const loading = computed(() => !d.value && !errorMessage.value)

const DOCSTATUS = {
	0: { teks: 'Draft', kelas: 'bg-ui-surface-gray-100 text-ui-ink-gray-600' },
	1: { teks: 'Submitted', kelas: 'bg-ui-surface-green-100 text-ui-ink-green-700' },
	2: { teks: 'Cancelled', kelas: 'bg-ui-surface-red-100 text-ui-ink-red-700' },
}
const docstatusPill = computed(() => DOCSTATUS[d.value?.docstatus] || DOCSTATUS[0])

// Warna titik pada ringkasan mengikuti ember yang sama dengan daftar & kartu Home.
const EMBER = {
	Hadir: 'bg-green-500',
	'Setengah Hari': 'bg-green-500',
	'Bekerja Dari Rumah': 'bg-green-500',
	'Tidak Scan IN': 'bg-green-500',
	'Tidak Scan OUT': 'bg-green-500',
	'Sudah Scan Masuk': 'bg-ui-surface-blue-400',
	Absen: 'bg-ui-surface-red-400',
	Cuti: 'bg-ui-surface-amber-400',
}
const warnaStatus = computed(() => EMBER[d.value?.status] || 'bg-ui-surface-gray-300')

// ---- Jembatan ke Keterlambatan --------------------------------------------
// Hanya untuk kehadiran MILIK SENDIRI: halaman tujuannya menolak dokumen milik
// orang lain, jadi menawarkan tautan itu kepada HR hanya akan berujung error.
const AJAKAN = {
	'Belum Diisi': { teks: 'Isi Alasan Keterlambatan', utama: true },
	'Tidak Dimaafkan': { teks: 'Ajukan Ulang Alasan', utama: true },
}

const tautanKeterlambatan = computed(() => {
	const doc = d.value
	if (!doc?.terlambat_masuk || !doc.keterlambatan || !doc.milik_saya) return null
	// Status selain kedua di atas sudah tidak menuntut tindakan karyawan —
	// tautannya tetap ada, tapi sebagai rujukan, bukan ajakan.
	return AJAKAN[doc.status_keterlambatan] || { teks: 'Lihat Alasan Keterlambatan', utama: false }
})

// ---- Jembatan ke Pulang Cepat ---------------------------------------------
const AJAKAN_PC = {
	'Belum Diisi': { teks: 'Isi Alasan Pulang Cepat', utama: true },
	'Tidak Dimaafkan': { teks: 'Ajukan Ulang Alasan', utama: true },
}

const tautanPulangCepat = computed(() => {
	const doc = d.value
	if (!doc?.kepulangan_cepat || !doc.milik_saya) return null
	return (
		AJAKAN_PC[doc.status_kepulangan_cepat] || {
			teks: 'Lihat Alasan Pulang Cepat',
			utama: false,
		}
	)
})

// Tombol tandai manual: hanya untuk kehadiran sendiri yang sudah scan masuk,
