// ---- Muat metadata doctype ------------------------------------------------
onMounted(async () => {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const meta = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (meta && meta.fields) || []
	} catch (e) {
		// Meta gagal dimuat → kartu ringkasan di atas tetap tampil.
		metaFields.value = []
	} finally {
		metaSiap.value = true
	}
})
